  function translate(root){if(!root)return;var walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,null,false),node;while(node=walker.nextNode())translateText(node);var elements=root.querySelectorAll?root.querySelectorAll('[placeholder],[title],[aria-label]'):[];for(var i=0;i<elements.length;i++){['placeholder','title','aria-label'].forEach(function(attr){var value=elements[i].getAttribute(attr);if(value&&translations[value])elements[i].setAttribute(attr,translations[value])})}}
